def patch_config(base: dict[str,str], patches: list[tuple[str,str,str]]) -> list[str] | None:
    m=base.copy()
    if '' in m: return None
    for op,key,value in patches:
        if not key: return None
        if op=='set': m[key]=value
        elif op=='unset': m.pop(key,None)
        else: return None
    return [f'{k}={m[k]}' for k in sorted(m)]
